'use client';

import React, { useMemo, useState, useSyncExternalStore } from 'react';
import Image from 'next/image';
import { useAccount, useConnect, useDisconnect } from 'wagmi';

type AppHeaderProps = {
  aiTakeoverEnabled?: boolean;
};

export function AppHeader({ aiTakeoverEnabled = false }: AppHeaderProps) {
  const [walletMenuOpen, setWalletMenuOpen] = useState(false);
  const hasHydrated = useSyncExternalStore(
    () => () => undefined,
    () => true,
    () => false
  );
  const { address, chain, isConnected } = useAccount();
  const { connect, connectors, isPending } = useConnect();
  const { disconnect } = useDisconnect();

  const shortAddress = useMemo(() => {
    if (!address) return 'Connect Wallet';
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  }, [address]);

  const walletButtonLabel = hasHydrated && isConnected ? shortAddress : 'Connect Wallet';

  return (
    <header className="brand-surface sticky top-0 z-50 border-b border-slate-900/10 bg-white/78 backdrop-blur-xl">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
        <div className="reveal-up rounded-[1.2rem] border border-slate-900/12 bg-white/90 px-3 py-2 shadow-[0_16px_34px_rgba(15,23,42,0.12)] sm:px-4">
        <div className="flex items-center justify-between gap-4">
          <div className="flex items-center gap-3 min-w-0">
            <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-white via-slate-50 to-cyan-50 border border-slate-900/12 flex items-center justify-center shadow-sm ring-1 ring-blue-200/45">
              <Image
                src="/branding/onabat-logo-light.png"
                alt="ONabat logo"
                width={32}
                height={32}
                className="h-8 w-8 object-contain"
                priority
              />
            </div>
            <div className="min-w-0">
              <h1 className="brand-display text-2xl sm:text-3xl font-extrabold tracking-tight text-slate-900 truncate">ONabat</h1>
              <p className="font-['IBM_Plex_Mono'] text-[10px] sm:text-[11px] uppercase tracking-[0.12em] text-slate-600 truncate">Institutional Omnichain Desk | Base + Arbitrum</p>
              {aiTakeoverEnabled && (
                <span className="mt-1 inline-flex items-center rounded-full border border-sky-500/40 bg-sky-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.14em] text-sky-800">
                  RAYAY Takeover Active
                </span>
              )}
            </div>
          </div>

          <div className="relative">
            <button
              type="button"
              onClick={() => setWalletMenuOpen((prev) => !prev)}
              className="inline-flex items-center gap-2 rounded-xl border border-slate-900/15 bg-white px-3 py-2 text-sm font-semibold text-slate-800 shadow-sm transition hover:-translate-y-0.5 hover:bg-slate-50"
            >
              <span className="h-2 w-2 rounded-full bg-sky-500" />
              <span>{walletButtonLabel}</span>
            </button>

            {walletMenuOpen && (
              <div className="absolute right-0 mt-2 w-72 rounded-xl border border-slate-900/10 bg-white/96 p-2 shadow-[0_18px_34px_rgba(15,23,42,0.16)] backdrop-blur">
                {hasHydrated && isConnected ? (
                  <div className="space-y-2">
                    <div className="rounded-lg border border-slate-900/10 bg-cyan-50/60 px-3 py-2 text-xs text-slate-700">
                      <p className="font-semibold text-slate-900">{shortAddress}</p>
                      <p>Chain: {chain?.name || 'Unknown'}</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        disconnect();
                        setWalletMenuOpen(false);
                      }}
                      className="w-full rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-sm font-semibold text-rose-700 transition hover:bg-rose-100"
                    >
                      Disconnect
                    </button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <p className="px-1 font-['IBM_Plex_Mono'] text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Connect Gateway</p>
                    {connectors.map((connector) => (
                      <button
                        key={connector.uid}
                        type="button"
                        disabled={Boolean(isPending)}
                        onClick={() => connect({ connector })}
                        className="w-full rounded-lg border border-slate-900/10 bg-white px-3 py-2 text-left text-sm font-semibold text-slate-800 transition hover:border-cyan-300/70 hover:bg-cyan-50 disabled:cursor-not-allowed disabled:opacity-60"
                      >
                        {connector.name}
                        {isPending ? ' (connecting...)' : ''}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
        </div>
      </div>
    </header>
  );
}
